    "WANDA's boyfriend in RUSTURF TUNNEL, once you break the boulder there with ROCK SMASH." to Tr(ja = "カナシダトンネルの いわを いわくだきで こわした あと ミチルの こいびと。", fr = "Le petit ami de SYLVIE dans le TUNNEL MERAZON, une fois le rocher brisé avec ECLATE-ROC.", de = "HEIKEs Freund im METAFLURTUNNEL, wenn du dort den Felsen mit ZERTRÜMMERER zerschlägst.", it = "Il ragazzo di LINDA nel TUNNEL MENFERRO, dopo che hai rotto il masso con SPACCAROCCIA.", es = "El novio de CLARA en el TÚNEL FERVERGAL, cuando rompas la roca con GOLPE ROCA.", zh = "用碎岩打碎巨石后，卡绿隧道里旺达的男友会给你。"),
    "HM05 FLASH" to Tr(ja = "ひでんマシン05 フラッシュ", fr = "CS05 FLASH", de = "VM05 BLITZ", it = "MN05 FLASH", es = "MO05 DESTELLO", zh = "秘传学习器05·闪光"),
