    "A hiker just inside GRANITE CAVE on DEWFORD's island." to Tr(ja = "ムロの しまに ある いしのどうくつの いりぐちの やまおとこ。", fr = "Un montagnard à l'entrée de la GROTTE GRANITE, sur l'île de MYOKARA.", de = "Ein Wanderer gleich am Eingang der GRANITHÖHLE auf der Insel von FAUSTAUHAVEN.", it = "Un montanaro appena dentro la GROTTA PIETROSA, sull'isola di BLURUVIA.", es = "Un montañero nada más entrar en la CUEVA GRANITO, en la isla de AZULIZA.", zh = "武斗所在岛上，石之洞窟入口处的登山者。"),
    "HM06 ROCK SMASH" to Tr(ja = "ひでんマシン06 いわくだき", fr = "CS06 ECLATE-ROC", de = "VM06 ZERTRÜMMERER", it = "MN06 SPACCAROCCIA", es = "MO06 GOLPE ROCA", zh = "秘传学习器06·碎岩"),
    "MAUVILLE CITY." to Tr(ja = "キンセツシティ。", fr = "LAVANDIA.", de = "MALVENFROH CITY.", it = "CICLAMIPOLI.", es = "CIUDAD MALVALONA.", zh = "紫堇市。"),
    "The ROCK SMASH GUY in a MAUVILLE CITY house." to Tr(ja = "キンセツシティの いえに いる いわくだきオヤジ。", fr = "Le TYPE ECLATE-ROC, dans une maison de LAVANDIA.", de = "Der ZERTRÜMMERER in einem Haus in MALVENFROH CITY.", it = "Il TIPO SPACCAROCCIA in una casa di CICLAMIPOLI.", es = "El MACHACARROCAS, en una casa de CIUDAD MALVALONA.", zh = "紫堇市一栋房子里的碎岩大叔。"),
    "HM07 WATERFALL" to Tr(ja = "ひでんマシン07 たきのぼり", fr = "CS07 CASCADE", de = "VM07 KASKADE", it = "MN07 CASCATA", es = "MO07 CASCADA", zh = "秘传学习器07·攀瀑"),
    "Late in the story, SOOTOPOLIS CITY." to Tr(ja = "ものがたりの おわりごろの ルネシティ。", fr = "Tard dans l'histoire, ATALANOPOLIS.", de = "Spät in der Geschichte, XENEROVILLE.", it = "Verso la fine della storia, CENERIDE.", es = "Al final de la historia, ARRECÍPOLIS.", zh = "剧情后期，琉璃市。"),
    "WALLACE in SOOTOPOLIS CITY, after the two ancient POKéMON are calmed." to Tr(ja = "2ひきの こだいの ポケモンが しずまった あと ルネシティの ミクリ。", fr = "MARC à ATALANOPOLIS, une fois les deux POKéMON antiques apaisés.", de = "WASSILI in XENEROVILLE, sobald die zwei uralten POKéMON beruhigt sind.", it = "ADRIANO a CENERIDE, dopo che i due POKéMON antichi si sono calmati.", es = "PLUBIO en ARRECÍPOLIS, cuando se calmen los dos POKéMON ancestrales.", zh = "两只古代宝可梦平息后，琉璃市的米可利。"),
    "HM08 DIVE" to Tr(ja = "ひでんマシン08 ダイビング", fr = "CS08 PLONGEE", de = "VM08 TAUCHER", it = "MN08 SUB", es = "MO08 BUCEO", zh = "秘传学习器08·潜水"),
    "MOSSDEEP CITY." to Tr(ja = "トクサネシティ。", fr = "ALGATIA.", de = "MOOSBACH CITY.", it = "VERDEAZZUPOLI.", es = "CIUDAD ALGARIA.", zh = "绿岭市。"),
    "STEVEN at his house in MOSSDEEP CITY, after the SPACE CENTER." to Tr(ja = "うちゅうセンターの あと トクサネシティの いえに いる ダイゴ。", fr = "PIERRE chez lui à ALGATIA, après le CENTRE SPATIAL.", de = "TROY in seinem Haus in MOOSBACH CITY, nach dem RAUMFAHRTZENTRUM.", it = "ROCCO a casa sua a VERDEAZZUPOLI, dopo il CENTRO SPAZIALE.", es = "MÁXIMO en su casa de CIUDAD ALGARIA, tras el CENTRO ESPACIAL.", zh = "宇宙中心事件后，绿岭市他家里找大吾。"),

    // WHERE IS: shops and services
    "SHOPS & SERVICES" to Tr(ja = "おみせと サービス", fr = "BOUTIQUES ET SERVICES", de = "LÄDEN & DIENSTE", it = "NEGOZI E SERVIZI", es = "TIENDAS Y SERVICIOS", zh = "商店与服务"),
    "Evolution stones" to Tr(ja = "しんかの いし", fr = "Pierres d'évolution", de = "Entwicklungssteine", it = "Pietre evolutive", es = "Piedras evolutivas", zh = "进化石"),
    "Diving treasure." to Tr(ja = "ダイビングで みつかる おたから。", fr = "Des trésors sous-marins.", de = "Schätze vom Meeresgrund.", it = "Tesori dei fondali.", es = "Tesoros del fondo marino.", zh = "潜水寻宝。"),
    "The TREASURE HUNTER's house on ROUTE 124 swaps shards found by DIVING: RED for a FIRE STONE, YELLOW for THUNDER, BLUE for WATER, GREEN for LEAF. Some lie around too: FIERY PATH (FIRE), ROUTE 119 (LEAF), NEW MAUVILLE (THUNDER), the ABANDONED SHIP (WATER), METEOR FALLS (MOON)." to Tr(ja = "124ばんすいどうの ハンターの こやで ダイビングで みつけた かけらを こうかん: あかいかけらは ほのおのいし、 きいろいかけらは かみなりのいし、 あおいかけらは みずのいし、 みどりのかけらは リーフのいし。 おちて いる ものも ある: ほのおのぬけみち (ほのお)、 119ばんどうろ (リーフ)、 ニューキンセツ (かみなり)、 すてられぶね (みず)、 りゅうせいのたき (つき)。", fr = "Le CHERCHEUR DE TRESORS du CHENAL 124 échange les TESSONS trouvés en PLONGEE : ROUGE contre une PIERRE FEU, JAUNE contre une PIERREFOUDRE, BLEU contre une PIERRE EAU, VERT contre une PIERREPLANTE. On en trouve aussi : CHEMIN ARDENT (FEU), ROUTE 119 (PLANTE), NEW LAVANDIA (FOUDRE), EPAVE (EAU), SITE METEORE (LUNE).", de = "Der SCHATZTAUCHER auf ROUTE 124 tauscht beim Tauchen gefundene STÜCKE: PURPUR gegen einen FEUERSTEIN, GELB gegen einen DONNERSTEIN, INDIGO gegen einen WASSERSTEIN, GRÜN gegen einen BLATTSTEIN. Manche liegen auch herum: FEURIGER PFAD (FEUER), ROUTE 119 (BLATT), NEU MALVENFROH (DONNER), SCHIFFSWRACK (WASSER), METEORFÄLLE (MOND).", it = "Il SUB CERCATESORI del PERCORSO 124 scambia i COCCI trovati con SUB: ROSSO per una PIETRAFOCAIA, GIALLO per una PIETRATUONO, BLU per una PIETRAIDRICA, VERDE per una PIETRAFOGLIA. Alcune sono in giro: CAMMINO ARDENTE (FOCAIA), PERCORSO 119 (FOGLIA), CICLANOVA (TUONO), VECCHIA NAVE (IDRICA), CASCATE METEORA (LUNARE).", es = "El BUSCATESOROS MARINOS de la RUTA 124 cambia las PARTES halladas con BUCEO: ROJA por una PIEDRA FUEGO, AMARILLA por una PIEDRATRUENO, AZUL por una PIEDRA AGUA, VERDE por una PIEDRA HOJA. Otras están por ahí: SENDA ÍGNEA (FUEGO), RUTA 119 (HOJA), MALVALANOVA (TRUENO), NAO ABANDONADA (AGUA), CASCADA METEORO (LUNAR).", zh = "124号道路的寻宝者家可以用潜水捡到的碎片换：红色碎片换火之石，黄色碎片换雷之石，蓝色碎片换水之石，绿色碎片换叶之石。也有几处能直接捡到：炎热小径（火之石）、119号道路（叶之石）、新紫堇（雷之石）、弃船（水之石）、流星瀑布（月之石）。"),
    "MOVE DELETER" to Tr(ja = "わざわすれじいさん", fr = "EFFACEUR DE CAPACITES", de = "ATTACKEN-VERLERNER", it = "ELIMINAMOSSE", es = "QUITA-MOVIMIENTOS", zh = "招式删除师"),
    "A house in LILYCOVE CITY." to Tr(ja = "ミナモシティの いえ。", fr = "Une maison à NENUCRIQUE.", de = "Ein Haus in SEEGRASULB CITY.", it = "Una casa a PORTO ALGHEPOLI.", es = "Una casa en CIUDAD CALAGUA.", zh = "水静市的一栋房子。"),
    "MOVE TUTOR" to Tr(ja = "わざおしえマニア", fr = "MAITRE DES CAPACITES", de = "ATTACKEN-HELFER", it = "GUIDA MOSSE", es = "TUTOR de MOVIMIENTOS", zh = "招式教学者"),
    "A house in FALLARBOR TOWN. Bring a HEART SCALE." to Tr(ja = "ハジツゲタウンの いえ。 ハートのウロコを もって いこう。", fr = "Une maison à AUTEQUIA. Apportez une ECAILLECOEUR.", de = "Ein Haus in LAUBWECHSELFELD. Bring eine HERZSCHUPPE mit.", it = "Una casa a BRUNIFOGLIA. Porta una SQUAMA CUORE.", es = "Una casa en PUEBLO PARDAL. Lleva una ESCAMA CORAZÓN.", zh = "秋叶镇的一栋房子。带一个心之鳞片。"),

