    "WYNAUT (egg)" to Tr(ja = "ソーナノ (タマゴ)", fr = "OKEOKE (ŒUF)", de = "ISSO (EI)", it = "WYNAUT (UOVO)", es = "WYNAUT (HUEVO)", zh = "小果然（蛋）"),
    "A hot-spring town." to Tr(ja = "おんせんの まち。", fr = "Un village thermal.", de = "Ein Ort mit heißen Quellen.", it = "Un paese termale.", es = "Un pueblo de aguas termales.", zh = "一座温泉小镇。"),
    "An old woman in LAVARIDGE TOWN." to Tr(ja = "フエンタウンの おばあさん。", fr = "Une vieille dame à VERMILAVA.", de = "Eine alte Frau in BAD LAVASTADT.", it = "Un'anziana a CUORDILAVA.", es = "Una anciana en PUEBLO LAVACALDA.", zh = "釜炎镇的一位老奶奶。"),
    "LILEEP / ANORITH" to Tr(ja = "リリーラ / アノプス", fr = "LILIA / ANORITH", de = "LILIEP / ANORITH", it = "LILEEP / ANORITH", es = "LILEEP / ANORITH", zh = "触手百合 / 太古羽虫"),
    "A tower in the desert." to Tr(ja = "さばくの とう。", fr = "Une tour dans le désert.", de = "Ein Turm in der Wüste.", it = "Una torre nel deserto.", es = "Una torre en el desierto.", zh = "沙漠里的一座塔。"),
    "Pick the ROOT or CLAW FOSSIL at the top of the MIRAGE TOWER in the ROUTE 111 desert; DEVON CORP. 2F in RUSTBORO CITY revives it." to Tr(ja = "111ばんどうろの さばくに ある げんえいのとうの てっぺんで ねっこのカセキか ツメのカセキを えらぶ。 カナズミシティの デボンコーポレーション 2かいで ふっかつ して もらえる。", fr = "Prenez le FOSS. RACINE ou le FOSS. GRIFFE au sommet de la TOUR MIRAGE, dans le désert de la ROUTE 111 ; le 1er étage de DEVON à MEROUVILLE le ranime.", de = "Nimm oben im WUNDERTURM in der Wüste auf ROUTE 111 das WURZELFOSSIL oder das KLAUENFOSSIL; im 1. Stock der DEVON CORPORATION in METAROST CITY wird es wiederbelebt.", it = "Prendi il RADIFOSSILE o il FOSSILUNGHIA in cima alla TORRE MIRAGGIO, nel deserto del PERCORSO 111; al 1º piano della DEVON SpA a FERRUGIPOLI lo rianimano.", es = "Coge el FÓSIL RAÍZ o el FÓSIL GARRA en lo alto de la TORRE ESPEJISMO, en el desierto de la RUTA 111; en la planta 1 de DEVON S.A., en CIUDAD FÉRRICA, lo reviven.", zh = "在 111号道路沙漠的幻影塔顶层选根状化石或爪状化石；卡那兹市的得文公司 2楼可以复活。"),
    "BELDUM" to Tr(ja = "ダンバル", fr = "TERHAL", de = "TANHEL", it = "BELDUM", es = "BELDUM", zh = "铁哑铃"),
    "Post-game." to Tr(ja = "エンディングの あと。", fr = "Après l'aventure principale.", de = "Nach dem Abspann.", it = "Dopo i titoli di coda.", es = "Tras terminar la historia.", zh = "通关后。"),
    "STEVEN's house in MOSSDEEP CITY, after the HALL OF FAME." to Tr(ja = "でんどういりの あと トクサネシティの ダイゴの いえ。", fr = "La maison de PIERRE à ALGATIA, après le PANTHEON DES DRESSEURS.", de = "TROYS Haus in MOOSBACH CITY, nach der RUHMESHALLE.", it = "La casa di ROCCO a VERDEAZZUPOLI, dopo la SALA d'ONORE.", es = "La casa de MÁXIMO en CIUDAD ALGARIA, tras el HALL de la FAMA.", zh = "进入名人堂后，绿岭市的大吾家。"),
    "CHIKORITA / CYNDAQUIL / TOTODILE" to Tr(ja = "チコリータ / ヒノアラシ / ワニノコ", fr = "GERMIGNON / HERICENDRE / KAIMINUS", de = "ENDIVIE / FEURIGEL / KARNIMANI", it = "CHIKORITA / CYNDAQUIL / TOTODILE", es = "CHIKORITA / CYNDAQUIL / TOTODILE", zh = "菊草叶 / 火球鼠 / 小锯鳄"),
    "Post-game, and a full HOENN DEX." to Tr(ja = "エンディングの あと。 ホウエンずかんを かんせい させて。", fr = "Après l'aventure, avec le POKéDEX de HOENN complet.", de = "Nach dem Abspann, mit vollem HOENN-POKéDEX.", it = "Dopo i titoli di coda, con il POKéDEX di HOENN completo.", es = "Tras la historia, con la POKéDEX de HOENN completa.", zh = "通关后，且集齐丰缘图鉴。"),
    "After the HALL OF FAME, catch every HOENN POKéMON (not JIRACHI or DEOXYS); PROF. BIRCH then lets you pick one." to Tr(ja = "でんどういりの あと ホウエンの ポケモンを ぜんぶ つかまえる (ジラーチと デオキシスは のぞく)。 すると オダマキはかせが 1ぴき えらばせて くれる。", fr = "Après le PANTHEON DES DRESSEURS, attrapez tous les POKéMON de HOENN (sauf JIRACHI et DEOXYS) ; le PROF. SEKO vous laisse alors en choisir un.", de = "Fang nach der RUHMESHALLE alle POKéMON aus HOENN (außer JIRACHI und DEOXYS); dann lässt PROF. BIRK dich eines wählen.", it = "Dopo la SALA d'ONORE, cattura tutti i POKéMON di HOENN (tranne JIRACHI e DEOXYS); poi il PROF. BIRCH te ne fa scegliere uno.", es = "Tras el HALL de la FAMA, atrapa todos los POKéMON de HOENN (salvo JIRACHI y DEOXYS); luego el PROF. ABEDUL te deja elegir uno.", zh = "进入名人堂后，捕捉丰缘的全部宝可梦（不含基拉祈、代欧奇希斯），小田卷博士就会让你三选一。"),

    // WHERE IS: legendary POKéMON
    "LEGENDARY POKéMON" to Tr(ja = "でんせつの ポケモン", fr = "POKéMON LEGENDAIRES", de = "LEGENDÄRE POKéMON", it = "POKéMON LEGGENDARI", es = "POKéMON LEGENDARIOS", zh = "传说的宝可梦"),
    "RAYQUAZA" to Tr(ja = "レックウザ", fr = "RAYQUAZA", de = "RAYQUAZA", it = "RAYQUAZA", es = "RAYQUAZA", zh = "烈空坐"),
    "A tower in the sea near PACIFIDLOG TOWN." to Tr(ja = "キナギタウンの ちかくの うみに たつ とう。", fr = "Une tour en mer près de PACIFIVILLE.", de = "Ein Turm im Meer bei FLOSSBRUNN.", it = "Una torre in mare vicino a OROCEA.", es = "Una torre en el mar cerca de PUEBLO OROMAR.", zh = "涟漪镇附近海上的高塔。"),
    "The top of the SKY PILLAR on ROUTE 131, once the story's SOOTOPOLIS CITY crisis is over. Some floors crack: ride the MACH BIKE across them." to Tr(ja = "ルネシティの じけんが おわった あと 131ばんすいどうの そらのはしらの てっぺん。 ひびの はいった ゆかは マッハじてんしゃで わたろう。", fr = "Au sommet du PILIER CELESTE (CHENAL 131), une fois la crise d'ATALANOPOLIS terminée. Certains sols se fissurent : traversez-les en VELO COURSE.", de = "Ganz oben im HIMMELTURM auf ROUTE 131, wenn die Krise in XENEROVILLE vorbei ist. Manche Böden brechen: Fahr mit dem EILRAD darüber.", it = "In cima alla TORRE dei CIELI sul PERCORSO 131, finita la crisi di CENERIDE. Alcuni pavimenti si crepano: attraversali con la BICI CORSA.", es = "En lo alto del PILAR CELESTE, en la RUTA 131, cuando acabe la crisis de ARRECÍPOLIS. Algunos suelos se agrietan: crúzalos con la BICI CARRERA.", zh = "131号道路的天空之柱顶层，需先结束琉璃市的剧情危机。有几层地面会裂：骑音速自行车冲过去。"),
    "GROUDON / KYOGRE" to Tr(ja = "グラードン / カイオーガ", fr = "GROUDON / KYOGRE", de = "GROUDON / KYOGRE", it = "GROUDON / KYOGRE", es = "GROUDON / KYOGRE", zh = "固拉多 / 盖欧卡"),
    "Post-game - watch the weather reports." to Tr(ja = "エンディングの あと。 てんきよほうに ちゅうもく。", fr = "Après l'aventure : suivez la météo.", de = "Nach dem Abspann - achte auf den Wetterbericht.", it = "Dopo i titoli di coda: segui il meteo.", es = "Tras la historia: atento al parte meteorológico.", zh = "通关后——留意天气播报。"),
    "After the HALL OF FAME, a scientist at the WEATHER INSTITUTE reports a drought or heavy rain on some route. A drought leads to TERRA CAVE (GROUDON), heavy rain to MARINE CAVE underwater (KYOGRE, use DIVE)." to Tr(ja = "でんどういりの あと てんきけんきゅうじょの けんきゅういんが どこかの どうろの ひでりや おおあめを おしえて くれる。 ひでりなら りくのどうくつ (グラードン)、 おおあめなら うみの なかの うみのどうくつ (カイオーガ、 ダイビングを つかう)。", fr = "Après le PANTHEON DES DRESSEURS, un chercheur du CENTRE METEO signale une sécheresse ou de fortes pluies sur une route. La sécheresse mène à la GROTTE TERRA (GROUDON), les pluies à la GROTTE MARINE sous l'eau (KYOGRE, avec PLONGEE).", de = "Nach der RUHMESHALLE meldet ein Forscher im KLIMA-INSTITUT eine Dürre oder Starkregen auf einer Route. Dürre führt zur TERRAHÖHLE (GROUDON), Starkregen zur OZEANHÖHLE unter Wasser (KYOGRE, mit TAUCHER).", it = "Dopo la SALA d'ONORE, uno scienziato dell'ISTITUTO METEO segnala siccità o piogge forti su un percorso. La siccità porta alla GROTTA TERRA (GROUDON), la pioggia alla GROTTA MARE sott'acqua (KYOGRE, usa SUB).", es = "Tras el HALL de la FAMA, un científico del INSTITUTO METEOROLÓGICO avisa de sequía o lluvias fuertes en alguna ruta. La sequía lleva a la CUEVA TERRENA (GROUDON); las lluvias, a la CUEVA MARINA bajo el agua (KYOGRE, usa BUCEO).", zh = "进入名人堂后，天气研究所的研究员会报告某条道路出现干旱或暴雨。干旱通往大地洞窟（固拉多），暴雨则在水下海底洞窟（盖欧卡，用潜水下去）。"),
    "REGIROCK / REGICE / REGISTEEL" to Tr(ja = "レジロック / レジアイス / レジスチル", fr = "REGIROCK / REGICE / REGISTEEL", de = "REGIROCK / REGICE / REGISTEEL", it = "REGIROCK / REGICE / REGISTEEL", es = "REGIROCK / REGICE / REGISTEEL", zh = "雷吉洛克 / 雷吉艾斯 / 雷吉斯奇鲁"),
    "It starts under the sea, with two particular POKéMON." to Tr(ja = "うみの そこで はじまる。 とくべつな 2ひきの ポケモンが ひつよう。", fr = "Ça commence sous la mer, avec deux POKéMON précis.", de = "Es beginnt unter dem Meer, mit zwei bestimmten POKéMON.", it = "Inizia sotto il mare, con due POKéMON precisi.", es = "Empieza bajo el mar, con dos POKéMON concretos.", zh = "从海底开始，需要两只特定的宝可梦。"),
    "First open the doors: put WAILORD first and RELICANTH last in your party and read the braille in the SEALED CHAMBER (DIVE on ROUTE 134). Then, after reading each ruin's braille: DESERT RUINS (ROUTE 111) - use ROCK SMASH; ANCIENT TOMB (ROUTE 120) - use FLASH; ISLAND CAVE (ROUTE 105) - walk one full lap along the walls." to Tr(ja = "まず とびらを ひらく: てもちの せんとうに ホエルオー、 さいごに ジーランスを いれて おふれのせきしつ (134ばんすいどうで ダイビング) の てんじを よむ。 つぎに それぞれの いせきの てんじを よんだ あと: さばくいせき (111ばんどうろ) は いわくだき、 こだいづか (120ばんどうろ) は フラッシュ、 こじまのよこあな (105ばんすいどう) は かべに そって 1しゅう あるく。", fr = "Ouvrez d'abord les portes : WAILORD en tête et RELICANTH en dernier dans l'équipe, lisez le braille du SANCTUAIRE (PLONGEE au CHENAL 134). Puis, après avoir lu le braille de chaque ruine : RUINES DESERT (ROUTE 111), utilisez ECLATE-ROC ; TOMBEAU ANTIQUE (ROUTE 120), FLASH ; GROTTE ISLAND (CHENAL 105), faites un tour complet le long des murs.", de = "Öffne zuerst die Türen: WAILORD an erster und RELICANTH an letzter Stelle im Team, dann lies die Blindenschrift in der SIEGELKAMMER (TAUCHER auf ROUTE 134). Danach, nachdem du jeweils die Blindenschrift gelesen hast: WÜSTENRUINE (ROUTE 111) - setz ZERTRÜMMERER ein; GRABMAL (ROUTE 120) - BLITZ; INSELHÖHLE (ROUTE 105) - lauf einmal ganz an den Wänden entlang.", it = "Prima apri le porte: WAILORD primo e RELICANTH ultimo in squadra, poi leggi il Braille nella SALA INCISA (SUB sul PERCORSO 134). Poi, dopo aver letto il Braille di ogni rovina: ROVINE SABBIOSE (PERCORSO 111) - usa SPACCAROCCIA; TOMBA ANTICA (PERCORSO 120) - FLASH; GROTTA INSULARE (PERCORSO 105) - fai un giro completo lungo le pareti.", es = "Primero abre las puertas: WAILORD el primero y RELICANTH el último del equipo, y lee el braille de la CÁMARA SELLADA (BUCEO en la RUTA 134). Después, tras leer el braille de cada ruina: RUINAS DESIERTO (RUTA 111), usa GOLPE ROCA; TUMBA ANTIGUA (RUTA 120), DESTELLO; CUEVA INSULAR (RUTA 105), da una vuelta entera junto a las paredes.", zh = "先开门：队伍首位放吼鲸王、末位放古空棘鱼，读封印之室（134号道路潜水）里的盲文。之后按各遗迹的盲文操作：沙漠遗迹（111号道路）用碎岩；古代坟墓（120号道路）用闪光；小岛横穴（105号道路）沿墙走满一整圈。"),
    "LATIAS / LATIOS" to Tr(ja = "ラティアス / ラティオス", fr = "LATIAS / LATIOS", de = "LATIAS / LATIOS", it = "LATIAS / LATIOS", es = "LATIAS / LATIOS", zh = "拉帝亚斯 / 拉帝欧斯"),
    "Post-game, at home." to Tr(ja = "エンディングの あと、 いえで。", fr = "Après l'aventure, à la maison.", de = "Nach dem Abspann, zu Hause.", it = "Dopo i titoli di coda, a casa.", es = "Tras la historia, en casa.", zh = "通关后，在家里。"),
    "After the HALL OF FAME, go home: a TV news flash asks the colour. RED makes LATIAS roam HOENN, BLUE makes LATIOS." to Tr(ja = "でんどういりの あと いえに かえると テレビの ニュースで いろを きかれる。 あかなら ラティアス、 あおなら ラティオスが ホウエンを かけまわる。", fr = "Après le PANTHEON DES DRESSEURS, rentrez chez vous : un flash info à la télé demande une couleur. ROUGE fait errer LATIAS dans HOENN, BLEU LATIOS.", de = "Geh nach der RUHMESHALLE nach Hause: Eine Eilmeldung im Fernsehen fragt nach der Farbe. Bei ROT streift LATIAS durch HOENN, bei BLAU LATIOS.", it = "Dopo la SALA d'ONORE, torna a casa: un notiziario in TV chiede il colore. ROSSO fa vagare LATIAS per HOENN, BLU LATIOS.", es = "Tras el HALL de la FAMA, vuelve a casa: un avance informativo en la tele pregunta el color. ROJO hace que LATIAS vague por HOENN; AZUL, LATIOS.", zh = "进入名人堂后回家：电视新闻会问颜色。选红色则拉帝亚斯在丰缘四处游走，选蓝色则拉帝欧斯。"),
    "KECLEON" to Tr(ja = "カクレオン", fr = "KECLEON", de = "KECLEON", it = "KECLEON", es = "KECLEON", zh = "变隐龙"),
    "You can't see it." to Tr(ja = "すがたが みえない。", fr = "Il est invisible.", de = "Man sieht es nicht.", it = "Non si vede.", es = "No se ve.", zh = "看不见它。"),
    "Invisible ones sit on ROUTES 119 and 120 and in FORTREE CITY. The DEVON SCOPE reveals them." to Tr(ja = "119ばんどうろと 120ばんどうろ、 ヒワマキシティに みえない カクレオンが いる。 デボンスコープで すがたが みえる。", fr = "Des KECLEON invisibles se cachent sur les ROUTES 119 et 120 et à CIMETRONELLE. Le DEVON SCOPE les révèle.", de = "Unsichtbare sitzen auf ROUTE 119 und 120 und in BAUMHAUSEN CITY. Der DEVON-SCOPE macht sie sichtbar.", it = "Ce ne sono di invisibili sui PERCORSI 119 e 120 e a FORESTOPOLI. Il DEVONSCOPIO li rivela.", es = "Hay algunos invisibles en las RUTAS 119 y 120 y en CIUDAD ARBORADA. El DETECTOR DEVON los revela.", zh = "隐形的个体分别待在 119号道路、120号道路和茵郁市。用得文观测镜显形。"),

    // STUCK?
    "EARLY GAME" to Tr(ja = "はじめの ほう", fr = "DÉBUT DU JEU", de = "SPIELBEGINN", it = "INIZIO", es = "PRINCIPIO", zh = "前期"),
    "How do I get to DEWFORD TOWN?" to Tr(ja = "ムロタウンへの いきかたは?", fr = "Comment aller au VILLAGE MYOKARA ?", de = "Wie komme ich nach FAUSTAUHAVEN?", it = "Come arrivo a BLURUVIA?", es = "¿Cómo llego a PUEBLO AZULIZA?", zh = "怎么去武斗镇？"),
    "An old sailor lost his pet." to Tr(ja = "ふるい ふなのりが ペットを なくした。", fr = "Un vieux marin a perdu son compagnon.", de = "Ein alter Seebär hat sein Haustier verloren.", it = "Un vecchio marinaio ha perso il suo animale.", es = "Un viejo marinero ha perdido a su mascota.", zh = "一位老水手丢了宠物。"),
    "MR. BRINEY sails you from his cottage on ROUTE 104 once you've rescued his PEEKO from TEAM AQUA in RUSTURF TUNNEL." to Tr(ja = "カナシダトンネルで アクアだんから ピーコちゃんを たすけると 104ばんどうろの こやから ハギろうじんが ふねで つれて いって くれる。", fr = "M. MARCO vous emmène en bateau depuis son cottage de la ROUTE 104 une fois son PIKO sauvé de la TEAM AQUA dans le TUNNEL MERAZON.", de = "MR. BRACK bringt dich von seiner Hütte auf ROUTE 104 mit dem Boot hin, sobald du sein PECKO im METAFLURTUNNEL vor TEAM AQUA gerettet hast.", it = "Il SIG. MARINO ti porta in barca dal suo cottage sul PERCORSO 104 dopo che hai salvato il suo PEEKO dal TEAM IDRO nel TUNNEL MENFERRO.", es = "El SR. ARENQUE te lleva en barco desde su casa de la RUTA 104 cuando rescatas a su PEEKO del EQUIPO AQUA en el TÚNEL FERVERGAL.", zh = "在卡绿隧道从水舰队手里救出他的皮可后，海男先生会从他 104号道路的小屋开船送你。"),
    "Where are the stolen DEVON GOODS?" to Tr(ja = "ぬすまれた デボンのにもつは どこ?", fr = "Où est le PACK DEVON volé ?", de = "Wo sind die gestohlenen DEVON-WAREN?", it = "Dov'è la MERCE DEVON rubata?", es = "¿Dónde están las PIEZAS DEVON robadas?", zh = "被抢的得文货物在哪？"),
    "Follow the thief east." to Tr(ja = "どろぼうを おって ひがしへ。", fr = "Suivez le voleur vers l'est.", de = "Folge dem Dieb nach Osten.", it = "Segui il ladro verso est.", es = "Sigue al ladrón hacia el este.", zh = "跟着小偷往东走。"),
    "A TEAM AQUA grunt fled into RUSTURF TUNNEL, east of RUSTBORO CITY. Beat him there." to Tr(ja = "アクアだんの したっぱが カナズミシティの ひがしの カナシダトンネルに にげこんだ。 そこで たおそう。", fr = "Un SBIRE de la TEAM AQUA s'est enfui dans le TUNNEL MERAZON, à l'est de MEROUVILLE. Battez-le là-bas.", de = "Ein RÜPEL von TEAM AQUA ist in den METAFLURTUNNEL östlich von METAROST CITY geflohen. Besiege ihn dort.", it = "Una RECLUTA del TEAM IDRO è fuggita nel TUNNEL MENFERRO, a est di FERRUGIPOLI. Battila lì.", es = "Un SOLDADO del EQUIPO AQUA huyó al TÚNEL FERVERGAL, al este de CIUDAD FÉRRICA. Derrótalo allí.", zh = "一个水舰队小兵逃进了卡那兹市东边的卡绿隧道，在那里打赢他。"),
    "PETALBURG CITY's gym won't let me in" to Tr(ja = "トウカシティの ジムに はいれない", fr = "L'ARENE de CLEMENTI-VILLE me refuse l'entrée", de = "Die ARENA in BLÜTENBURG CITY lässt mich nicht rein", it = "La PALESTRA di PETALIPOLI non mi fa entrare", es = "No me dejan entrar al GIMNASIO de CIUDAD PETALIA", zh = "橙华市的道馆不让我进"),
    "Come back with more badges." to Tr(ja = "もっと バッジを あつめて から。", fr = "Revenez avec plus de badges.", de = "Komm mit mehr Orden wieder.", it = "Torna con più medaglie.", es = "Vuelve con más medallas.", zh = "多拿几枚徽章再来。"),
    "Your father NORMAN battles you once you have four badges." to Tr(ja = "バッジが 4こ あれば おとうさんの センリが たたかって くれる。", fr = "Votre père NORMAN vous affronte dès que vous avez quatre badges.", de = "Dein Vater NORMAN kämpft gegen dich, sobald du vier Orden hast.", it = "Tuo padre NORMAN ti sfida quando hai quattro medaglie.", es = "Tu padre NORMAN lucha contigo cuando tengas cuatro medallas.", zh = "拿到四枚徽章后，你父亲千里才会跟你打。"),
    "MID GAME" to Tr(ja = "なかごろ", fr = "MILIEU DU JEU", de = "SPIELMITTE", it = "METÀ GIOCO", es = "MITAD", zh = "中期"),
    "TEAM MAGMA blocks the cable car on ROUTE 112" to Tr(ja = "112ばんどうろの ロープウェイを マグマだんが ふさいで いる", fr = "La TEAM MAGMA bloque le TELEPHERIQUE de la ROUTE 112", de = "TEAM MAGMA versperrt die SEILBAHN auf ROUTE 112", it = "Il TEAM MAGMA blocca la FUNIVIA sul PERCORSO 112", es = "El EQUIPO MAGMA bloquea el TELEFÉRICO de la RUTA 112", zh = "112号道路的缆车被火岩队挡住"),
    "Go around the mountain." to Tr(ja = "やまを まわりこもう。", fr = "Faites le tour de la montagne.", de = "Geh um den Berg herum.", it = "Fai il giro della montagna.", es = "Rodea la montaña.", zh = "绕山过去。"),
    "They leave after the scene at METEOR FALLS - go north from MAUVILLE CITY on ROUTE 111, then west on ROUTE 113 to FALLARBOR TOWN and ROUTE 114." to Tr(ja = "りゅうせいのたきの できごとの あとで いなくなる。 キンセツシティから 111ばんどうろを きたへ、 113ばんどうろを にしへ すすみ ハジツゲタウンと 114ばんどうろへ。", fr = "Ils partent après la scène du SITE METEORE : allez au nord de LAVANDIA par la ROUTE 111, puis à l'ouest par la ROUTE 113 vers AUTEQUIA et la ROUTE 114.", de = "Sie ziehen nach der Szene bei den METEORFÄLLEN ab - geh von MALVENFROH CITY über ROUTE 111 nach Norden, dann über ROUTE 113 nach Westen nach LAUBWECHSELFELD und zu ROUTE 114.", it = "Se ne vanno dopo la scena alle CASCATE METEORA: da CICLAMIPOLI vai a nord sul PERCORSO 111, poi a ovest sul PERCORSO 113 fino a BRUNIFOGLIA e al PERCORSO 114.", es = "Se van tras la escena de la CASCADA METEORO: desde CIUDAD MALVALONA ve al norte por la RUTA 111 y luego al oeste por la RUTA 113 hasta PUEBLO PARDAL y la RUTA 114.", zh = "流星瀑布那场剧情之后他们就撤了——从紫堇市沿 111号道路北上，再走 113号道路往西到秋叶镇，接 114号道路。"),
    "A sandstorm keeps pushing me back on ROUTE 111" to Tr(ja = "111ばんどうろで すなあらしに おしもどされる", fr = "Une tempête de sable me repousse sur la ROUTE 111", de = "Ein Sandsturm drängt mich auf ROUTE 111 zurück", it = "Una tempesta di sabbia mi respinge sul PERCORSO 111", es = "Una tormenta de arena me hace retroceder en la RUTA 111", zh = "111号道路的沙暴一直把我推回去"),
    "Protect your eyes." to Tr(ja = "めを まもろう。", fr = "Protégez vos yeux.", de = "Schütze deine Augen.", it = "Proteggi gli occhi.", es = "Protégete los ojos.", zh = "保护好眼睛。"),
    "You need the GO-GOGGLES, from your rival in LAVARIDGE TOWN after the fourth badge." to Tr(ja = "4つめの バッジの あと フエンタウンで ライバルに もらえる ゴーゴーゴーグルが ひつよう。", fr = "Il vous faut les LUNET. SABLE, que votre rival donne à VERMILAVA après le quatrième badge.", de = "Du brauchst das WÜSTENGLAS, das dir dein Rivale nach dem vierten Orden in BAD LAVASTADT gibt.", it = "Ti servono gli OCCHIALONI, che il tuo rivale ti dà a CUORDILAVA dopo la quarta medaglia.", es = "Necesitas las GAFAS AISLANTES, que te da tu rival en PUEBLO LAVACALDA tras la cuarta medalla.", zh = "需要护目镜：打完第四枚徽章后，你的劲敌会在釜炎镇给你。"),
    "Something invisible blocks FORTREE CITY's gym" to Tr(ja = "ヒワマキシティの ジムの まえを みえない なにかが ふさいで いる", fr = "Quelque chose d'invisible bloque l'ARENE de CIMETRONELLE", de = "Etwas Unsichtbares versperrt die ARENA in BAUMHAUSEN CITY", it = "Qualcosa di invisibile blocca la PALESTRA di FORESTOPOLI", es = "Algo invisible bloquea el GIMNASIO de CIUDAD ARBORADA", zh = "茵郁市的道馆被什么隐形的东西挡住"),
    "Look east of FORTREE CITY." to Tr(ja = "ヒワマキシティの ひがしを さがそう。", fr = "Cherchez à l'est de CIMETRONELLE.", de = "Sieh dich östlich von BAUMHAUSEN CITY um.", it = "Cerca a est di FORESTOPOLI.", es = "Busca al este de CIUDAD ARBORADA.", zh = "去茵郁市东边看看。"),
    "It's a KECLEON. Get the DEVON SCOPE from STEVEN on ROUTE 120, then use it on the blocked spot." to Tr(ja = "カクレオンだ。 120ばんどうろで ダイゴから デボンスコープを もらい ふさがれた ばしょで つかおう。", fr = "C'est un KECLEON. Obtenez le DEVON SCOPE auprès de PIERRE sur la ROUTE 120, puis utilisez-le devant l'obstacle.", de = "Es ist ein KECLEON. Hol dir den DEVON-SCOPE von TROY auf ROUTE 120 und setz ihn an der versperrten Stelle ein.", it = "È un KECLEON. Prendi il DEVONSCOPIO da ROCCO sul PERCORSO 120 e usalo nel punto bloccato.", es = "Es un KECLEON. Consigue el DETECTOR DEVON de MÁXIMO en la RUTA 120 y úsalo en el sitio bloqueado.", zh = "是一只变隐龙。在 120号道路从大吾处拿到得文观测镜，对着被挡的位置使用。"),
    "LATE GAME" to Tr(ja = "おわりの ほう", fr = "FIN DU JEU", de = "SPIELENDE", it = "FINALE", es = "FINAL", zh = "后期"),
    "How do I get into SOOTOPOLIS CITY?" to Tr(ja = "ルネシティへの はいりかたは?", fr = "Comment entrer à ATALANOPOLIS ?", de = "Wie komme ich nach XENEROVILLE?", it = "Come entro a CENERIDE?", es = "¿Cómo entro en ARRECÍPOLIS?", zh = "怎么进琉璃市？"),
    "From below." to Tr(ja = "したから。", fr = "Par en dessous.", de = "Von unten.", it = "Da sotto.", es = "Desde abajo.", zh = "从水下去。"),
    "It sits inside a crater: DIVE down on ROUTE 126 and surface inside." to Tr(ja = "クレーターの なかに ある。 126ばんすいどうで ダイビングで もぐり なかで うきあがろう。", fr = "Elle est dans un cratère : utilisez PLONGEE au CHENAL 126 et remontez à l'intérieur.", de = "Es liegt in einem Krater: Tauch auf ROUTE 126 mit TAUCHER ab und drinnen wieder auf.", it = "Si trova in un cratere: usa SUB sul PERCORSO 126 e riemergi all'interno.", es = "Está dentro de un cráter: usa BUCEO en la RUTA 126 y sal a la superficie dentro.", zh = "它在一座环形山口里：在 126号道路用潜水下潜，再浮上来就在城里。"),
    "SOOTOPOLIS CITY's gym is closed" to Tr(ja = "ルネシティの ジムが しまって いる", fr = "L'ARENE d'ATALANOPOLIS est fermée", de = "Die ARENA in XENEROVILLE ist geschlossen", it = "La PALESTRA di CENERIDE è chiusa", es = "El GIMNASIO de ARRECÍPOLIS está cerrado", zh = "琉璃市的道馆没开"),
    "Someone in SOOTOPOLIS CITY knows what to do." to Tr(ja = "ルネシティの だれかが しって いる。", fr = "Quelqu'un à ATALANOPOLIS sait quoi faire.", de = "Jemand in XENEROVILLE weiß, was zu tun ist.", it = "Qualcuno a CENERIDE sa cosa fare.", es = "Alguien en ARRECÍPOLIS sabe qué hacer.", zh = "琉璃市里有人知道该怎么办。"),
    "Calm the two ancient POKéMON first: WALLACE sends you to the SKY PILLAR on ROUTE 131." to Tr(ja = "まず 2ひきの こだいの ポケモンを しずめよう。 ミクリが 131ばんすいどうの そらのはしらへ いかせて くれる。", fr = "Apaisez d'abord les deux POKéMON antiques : MARC vous envoie au PILIER CELESTE (CHENAL 131).", de = "Beruhige zuerst die zwei uralten POKéMON: WASSILI schickt dich zum HIMMELTURM auf ROUTE 131.", it = "Prima calma i due POKéMON antichi: ADRIANO ti manda alla TORRE dei CIELI sul PERCORSO 131.", es = "Primero calma a los dos POKéMON ancestrales: PLUBIO te envía al PILAR CELESTE de la RUTA 131.", zh = "先平息两只古代宝可梦：米可利会让你去 131号道路的天空之柱。"),
    "How do I reach EVER GRANDE CITY?" to Tr(ja = "サイユウシティへの いきかたは?", fr = "Comment aller à ETERNARA ?", de = "Wie erreiche ich PRACHTPOLIS CITY?", it = "Come raggiungo IRIDOPOLI?", es = "¿Cómo llego a CIUDAD COLOSALIA?", zh = "怎么去彩幽市？"),
    "Go up." to Tr(ja = "うえへ。", fr = "Montez.", de = "Nach oben.", it = "Sali.", es = "Sube.", zh = "往上去。"),
    "It's up a waterfall: you need HM07 WATERFALL (from WALLACE) and the RAIN BADGE." to Tr(ja = "たきの うえに ある。 ひでんマシン07 たきのぼり (ミクリから) と レインバッジが ひつよう。", fr = "Elle est en haut d'une cascade : il faut la CS07 CASCADE (de MARC) et le BADGE PLUIE.", de = "Es liegt oberhalb eines Wasserfalls: Du brauchst VM07 KASKADE (von WASSILI) und den SCHAUERORDEN.", it = "È in cima a una cascata: servono la MN07 CASCATA (da ADRIANO) e la MEDAGLIA PIOGGIA.", es = "Está en lo alto de una cascada: necesitas la MO07 CASCADA (de PLUBIO) y la MEDALLA LLUVIA.", zh = "它在瀑布上方：需要秘传学习器07·攀瀑（米可利给的）和雨滴徽章。"),

